1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  /** Zero-based index of the quote step that created the policy. */
21	  policy: number;
22	  incident: { cause: string; damages: Damage[] };
23	};
24	
25	export type Step = QuoteStep | ClaimStep;
26	
27	export type Customer = {
28	  yearsWithMHPCO: number;
29	};
30	
31	export type Scenario = {
32	  customer: Customer;
33	  steps: Step[];
34	};
35	
36	export type ScenarioResult = {
37	  results: unknown[];
38	};
39	
40	const PROCESSING_FEE = 5;
41	
42	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
43	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The item types the MHPCO will insure, and what each costs to cover. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/**
56	 * Premium for a single item of this type. A type the MHPCO does not insure yields
57	 * NaN, which propagates to the quote. Rejecting unknown types with a real error is
58	 * specified by a test we have not reached yet.
59	 */
60	const unitPremiumFor = (type: string): number => BASE_PREMIUMS[type] ?? NaN;
61	
62	/** Component types that form discounted blocks. */
63	const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
64	const COMPONENT_BLOCK_SIZE = 3;
65	const COMPONENT_BLOCK_PREMIUM = 60;
66	
67	const formsComponentBlock = (type: string, count: number): boolean =>
68	  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
69	
70	/** How many items of each type the policy covers. */
71	const countByType = (items: Item[]): Map<string, number> =>
72	  items.reduce(
73	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
74	    new Map<string, number>(),
75	  );
76	
77	/** Alike components form a discounted block; everything else is priced per unit. */
78	const basePremiumForGroup = (type: string, count: number): number =>
79	  formsComponentBlock(type, count)
80	    ? COMPONENT_BLOCK_PREMIUM
81	    : count * unitPremiumFor(type);
82	
83	const policyBasePremium = (items: Item[]): number =>
84	  [...countByType(items)].reduce(
85	    (total, [type, count]) => total + basePremiumForGroup(type, count),
86	    0,
87	  );
88	
89	/** A modifier that applies to some subject, contributing a rate when it does. */
90	type ModifierRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
91	
92	/** Modifier rates stack additively — at both the item and the policy level. */
93	const sumApplicableRates = <Subject>(
94	  rules: ModifierRule<Subject>[],
95	  subject: Subject,
96	): number =>
97	  rules.reduce((total, rule) => (rule.applies(subject) ? total + rule.rate : total), 0);
98	
99	const CURSE_SURCHARGE_RATE = 0.5;
100	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	
103	/** Each risk an item can carry, and the surcharge rate it attracts. */
104	const ITEM_SURCHARGE_RULES: ModifierRule<Item>[] = [
105	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
106	  {
107	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
108	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
109	  },
110	];
111	
112	/** Item-level surcharge rates stack additively on one item. */
113	const surchargeRateFor = (item: Item): number =>
114	  sumApplicableRates(ITEM_SURCHARGE_RULES, item);
115	
116	/**
117	 * Item-level surcharges apply to the affected item's own base premium, not to
118	 * the policy total.
119	 */
120	const itemSurchargeTotal = (items: Item[]): number =>
121	  items.reduce(
122	    (total, item) => total + unitPremiumFor(item.type) * surchargeRateFor(item),
123	    0,
124	  );
125	
126	const LOYALTY_DISCOUNT_RATE = 0.2;
127	const LOYALTY_YEARS_THRESHOLD = 2;
128	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
129	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
130	
131	/** A quote in the context of the customer's history with the MHPCO. */
132	type Contract = {
133	  customer: Customer;
134	  /** How many contracts this customer already held when this quote was made. */
135	  precedingContracts: number;
136	};
137	
138	/** Each policy-level modifier, and the rate it contributes. Discounts are negative. */
139	const POLICY_MODIFIER_RULES: ModifierRule<Contract>[] = [
140	  {
141	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
142	    rate: -LOYALTY_DISCOUNT_RATE,
143	  },
144	  // Every quote insures its items for the first time, whatever the customer's history.
145	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
146	  {
147	    applies: ({ precedingContracts }) => precedingContracts > 0,
148	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
149	  },
150	];
151	
152	/**
153	 * Policy-level modifiers are percentages of the policy base premium and stack
154	 * additively, per the MHPCO's worked examples.
155	 */
156	const policyModifierRate = (contract: Contract): number =>
157	  sumApplicableRates(POLICY_MODIFIER_RULES, contract);
158	
159	/**
160	 * Every modifier is a percentage of a base premium, and they are summed as flat
161	 * amounts rather than compounded: item surcharges are percentages of the affected
162	 * item's own base premium, policy modifiers percentages of the policy base premium
163	 * (the sum of all item base premiums, before any surcharge).
164	 */
165	const quotePremium = (items: Item[], contract: Contract): number => {
166	  const policyBase = policyBasePremium(items);
167	  const policyModifiers = policyBase * policyModifierRate(contract);
168	  const total = policyBase + itemSurchargeTotal(items) + policyModifiers + PROCESSING_FEE;
169	  return roundUpToWholeG(total);
170	};
171	
172	/** What each item type is insured for. */
173	const INSURANCE_VALUES: Record<string, number> = {
174	  sword: 1000,
175	  amulet: 600,
176	  staff: 800,
177	  potion: 400,
178	  rune: 250,
179	  moonstone: 250,
180	};
181	
182	const DEDUCTIBLE_PER_DAMAGE = 100;
183	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
184	
185	/** Payouts round down — in the MHPCO's favour. Float noise is discarded first. */
186	const roundDownToWholeG = (amount: number): number => Math.floor(Number(amount.toFixed(6)));
187	
188	/** A policy created by a quote step, tracked across the claims made against it. */
189	type Policy = {
190	  items: Item[];
191	  remainingCap: number;
192	};
193	
194	const openPolicy = (items: Item[]): Policy => {
195	  const insuranceSum = items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? NaN), 0);
196	  return { items, remainingCap: insuranceSum * CAP_MULTIPLE_OF_INSURANCE_SUM };
197	};
198	
199	/** A deductible applies once per damaged item. */
200	const payoutForDamage = (damage: Damage): number =>
201	  Math.max(0, damage.amount - DEDUCTIBLE_PER_DAMAGE);
202	
203	const settleClaim = (policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } => {
204	  const desired = damages.reduce((total, damage) => total + payoutForDamage(damage), 0);
205	  const payout = roundDownToWholeG(Math.min(desired, policy.remainingCap));
206	  policy.remainingCap -= payout;
207	  return { payout, remainingCap: policy.remainingCap };
208	};
209	
210	export const runScenario = (scenario: Scenario): ScenarioResult => {
211	  const policies = new Map<number, Policy>();
212	
213	  const results = scenario.steps.map((step, index) => {
214	    if (step.op === "claim") {
215	      const policy = policies.get(step.policy)!;
216	      return settleClaim(policy, step.incident.damages);
217	    }
218	
219	    policies.set(index, openPolicy(step.items));
220	    return {
221	      premium: quotePremium(step.items, {
222	        customer: scenario.customer,
223	        precedingContracts: policies.size - 1,
224	      }),
225	    };
226	  });
227	
228	  return { results };
229	};
